let e={value:null,addProjectionMetrics:null},recordStats=()=>{if(e.value!=null){e.value=null;e.addProjectionMetrics=null;throw new Error("Stats are already being measured")}let b={layoutProjection:null};b.layoutProjection={nodes:[],calculatedTargetDeltas:[],calculatedProjections:[]};e.value=b;e.addProjectionMetrics=a=>{b.layoutProjection.nodes.push(a.nodes);b.layoutProjection.calculatedTargetDeltas.push(a.calculatedTargetDeltas);b.layoutProjection.calculatedProjections.push(a.calculatedProjections)}};export{recordStats};